}

pub(crate) fn lose_ack<
    TW: AnchorWitnessStore + Send + 'static,
    RW: AnchorWitnessStore + Send + 'static,
>(
    owner: Arc<OriginalCellQ24TrainingCommandOwnerV1<TW, RW>>,
    mut channel: HostAuthorityPeerChannel,
) -> std::thread::JoinHandle<anyhow::Result<()>> {
    std::thread::spawn(move || {
        let mut completed_before_ack = false;
        let result = channel.exchange(|bytes| {
            let response = owner
                .command_response(bytes, 1)
                .map_err(|_| HostIssuerTransportError::InvalidRequest)?;
            let response: wire::Response = serde_json::from_slice(&response)
                .map_err(|_| HostIssuerTransportError::InvalidRequest)?;
            if !matches!(response.result, wire::CommandResult::Completed { .. }) {
                return Err(HostIssuerTransportError::InvalidRequest);
            }
            completed_before_ack = true;
            // The actual native/Generator completion exists. Only its response
            // is lost here; this injects no completion bytes or signature.
            Err(HostIssuerTransportError::Unavailable)
        });
        anyhow::ensure!(
            completed_before_ack,
            "actual original completion before lost ACK"
        );
        anyhow::ensure!(result.is_err(), "lost ACK closes the original channel");
        Ok(())
    })
}

pub(crate) fn reject_wrong_actor<
    TW: AnchorWitnessStore + Send + 'static,
    RW: AnchorWitnessStore + Send + 'static,
>(
    owner: Arc<OriginalCellQ24TrainingCommandOwnerV1<TW, RW>>,
) -> std::thread::JoinHandle<anyhow::Result<()>> {
    std::thread::spawn(move || {
        let mut request = wire::Request::new(
            &owner.context,
            owner.binding,
            1,
            wire::Action::Execute,
            false,
        );
        request.actor_id = "unregistered-command-actor".into();
        anyhow::ensure!(
            owner
                .command_response(&serde_json::to_vec(&request)?, 1)
                .is_err()
        );
        Ok(())
    })
}

pub(crate) fn reject_cancelled_queued_dispatch(
    context: OriginalCellQ24TrainingCommandContextV1,
) -> anyhow::Result<()> {
    std::thread::spawn(move || -> anyhow::Result<()> {
        let runtime = tokio::runtime::Builder::new_current_thread()
            .max_blocking_threads(1)
            .enable_all()
            .build()?;
        runtime.block_on(async move {
            let (client, mut channel) = client(context, false, None)?;
            let server = std::thread::spawn(move || -> anyhow::Result<()> {
                let mut delivered = false;
                let result = channel.exchange(|_| {
                    delivered = true;
                    Err(HostIssuerTransportError::Unavailable)
                });
                anyhow::ensure!(!delivered, "cancelled queued request reached the socket");
                anyhow::ensure!(matches!(result, Ok(false)), "unused connection must close");
                Ok(())
            });

            // Occupy the only blocking worker before polling the real client.
            // The Execute future has sampled false and moved its original
            // connection before its socket-request closure can begin.
            let (occupied_tx, occupied_rx) = tokio::sync::oneshot::channel();
            let (release_tx, release_rx) = std::sync::mpsc::channel();
            let blocker = tokio::task::spawn_blocking(move || {
                let _ = occupied_tx.send(());
                release_rx.recv()
            });
            occupied_rx.await?;
            let cancellation = Arc::new(AtomicBool::new(false));
            let mut execute = Box::pin(client.execute_training(Arc::clone(&cancellation)));
            std::future::poll_fn(|cx| match std::future::Future::poll(execute.as_mut(), cx) {
                std::task::Poll::Pending => std::task::Poll::Ready(()),
                std::task::Poll::Ready(_) => panic!("Execute must queue behind the blocker"),
            })
            .await;
            cancellation.store(true, Ordering::Release);
            release_tx.send(())?;
            blocker.await??;
            anyhow::ensure!(
                matches!(execute.await, Err(super::Error::Cancelled)),
                "the original cancellation token must be sampled before sending"
            );
            anyhow::ensure!(
                matches!(client.readback().await, Err(super::Error::Unavailable)),
                "cancellation must consume the original connection"
            );
            anyhow::ensure!(
                matches!(
                    client
                        .execute_training(Arc::new(AtomicBool::new(false)))
                        .await,
                    Err(super::Error::Unavailable)
                ),
                "cancellation must not restore an executable connection"
            );
            drop(client);
            server.join().expect("cancelled original socket")?;
            Ok(())
        })
    })
    .join()
    .expect("queued cancellation runtime")
}

/// Fixed, explicitly synthetic signed Training metadata over the actual
/// command codec. Only readback is accepted; no optimizer or signer is served.
pub(crate) fn retained_publication_training_peer(
    context: OriginalCellQ24TrainingCommandContextV1,
    receipt: codex_hepta_learning_artifacts::LearningIterationReceiptV1,
    signature: codex_hepta_learning_ledger::SignedLearningEvidenceV1,
) -> anyhow::Result<(
    OriginalCellQ24TrainingCommandClientV1,
    std::thread::JoinHandle<anyhow::Result<usize>>,
)> {
    let (client, channel) = client(context.clone(), /*readback_only*/ true, None)?;
    Ok((
        client,
        serve_retained_training_fixture(channel, context, receipt, signature)?,
    ))
}

/// Explicit signed metadata on the existing initial connection. This is not
/// an execution of Training and never claims to prove native learning.
pub(crate) fn retained_version_training_connection(
    material: crate::OriginalCellQ24MaterialReceiptConfigV1,
    context: OriginalCellQ24TrainingCommandContextV1,
    receipt: codex_hepta_learning_artifacts::LearningIterationReceiptV1,
    signature: codex_hepta_learning_ledger::SignedLearningEvidenceV1,
) -> anyhow::Result<(
    crate::OriginalCellQ24TrainingCommandConnectionV1,
    std::thread::JoinHandle<anyhow::Result<usize>>,
)> {
    let (connection, channel) =
        super::super::connection::fresh_peer(material, Duration::from_secs(300))?;
    Ok((
        connection,
        serve_retained_training_fixture(channel, context, receipt, signature)?,
    ))
}

fn serve_retained_training_fixture(
    mut channel: HostAuthorityPeerChannel,
    context: OriginalCellQ24TrainingCommandContextV1,
    receipt: codex_hepta_learning_artifacts::LearningIterationReceiptV1,
    signature: codex_hepta_learning_ledger::SignedLearningEvidenceV1,
) -> anyhow::Result<std::thread::JoinHandle<anyhow::Result<usize>>> {
    let binding = context.binding()?;
    let server = std::thread::spawn(move || -> anyhow::Result<usize> {
        let mut next = 1;
        loop {
            let observed = channel.exchange(|bytes| {
                let request: wire::Request = serde_json::from_slice(bytes)
                    .map_err(|_| HostIssuerTransportError::InvalidRequest)?;
                request
                    .require_context(&context, binding, next)
                    .map_err(|_| HostIssuerTransportError::InvalidRequest)?;
                if request.action != wire::Action::Readback || next > 64 {
                    return Err(HostIssuerTransportError::InvalidRequest);
                }
                let result = wire::encode_completed(
                    &context,
                    receipt.clone(),
                    signature.clone(),
                    super::super::now().map_err(|_| HostIssuerTransportError::InvalidRequest)?,
                )
                .map_err(|_| HostIssuerTransportError::InvalidRequest)?;
                let response = wire::Response::from_request(&request, result);
                next += 1;
                serde_json::to_vec(&response).map_err(|_| HostIssuerTransportError::InvalidRequest)
            })?;
            if !observed {
                return Ok((next - 1) as usize);
            }
        }
    });
    Ok(server)
}

// This method is compiled only through serving::command_test_support. It is
// a single synchronous observation of the already held original Stage, not
// a command, a new connection, or a receipt/signing-custody constructor.
impl<TW: AnchorWitnessStore + Send + 'static, RW: AnchorWitnessStore + Send + 'static>
    OriginalCellQ24TrainingCommandOwnerV1<TW, RW>
{
    pub(crate) fn fixture_completed_candidate_receipt(
        &self,
    ) -> Result<Option<OriginalCellQ24TrainingCommandReceiptV1>, super::Error> {
        use codex_hepta_intelligence_eval::ProductEvaluationExecutionStoreErrorV1 as Store;
        use crate::CellQ24TrainingOwnerErrorV1 as Native;
        use crate::OriginalCellQ24TrainingReceiptErrorV1 as Receipt;
        use crate::OriginalCellQ24TrainingStageErrorV1 as Stage;
        use crate::learning_owner_journal::LearningOriginalOwnerErrorV1 as Owner;

        let material = match crate::SourceBoundCellQ24TrainingStageV1::read_candidate_material(
            &self.stage,
            &self.context.dataset,
        ) {
            Ok(material) => material,
            // Exactly the non-completed states already distinguished by the
            // original command service. No other read failure becomes None.
            Err(Stage::Busy)
            | Err(Stage::Training(Native::Pending))
            | Err(Stage::Receipt(Receipt::Training(Native::Pending)))
            | Err(Stage::Receipt(Receipt::Owner(Owner::Pending)))
            | Err(Stage::Training(Native::Store(Store::Missing)))
            | Err(Stage::Receipt(Receipt::Training(Native::Store(Store::Missing))))
            | Err(Stage::Receipt(Receipt::Owner(Owner::Store(Store::Missing)))) => {
                return Ok(None);
            }
            Err(error) => return Err(error.into()),
        };
        // The original material lane has re-read both original owners and the
        // live source before and after its work. Authenticate those exact
        // retained bytes with the original command context and current time.
        let original = wire::authenticate_receipt(
            &self.context,
            material.receipt().clone(),
            material.attestation().clone(),
            super::super::now()?,
        )?;
        Ok(Some(original))
    }
}

